<?php require __DIR__.'/_start.php';$a=$appointment; ?>
<section class="customer-card"><div class="section-heading"><h2>Randevu #<?= (int)$a['id'] ?></h2><span class="status-pill status-<?= e($a['status']) ?>"><?= e($labels[$a['status']]) ?></span></div><dl class="booking-summary"><dt>Müşteri</dt><dd><?= e($a['customer_name']) ?></dd><dt>Hizmet</dt><dd><?= e($a['service_name']) ?></dd><dt>Tarih / saat</dt><dd><?= e(date('d.m.Y H:i',strtotime($a['start_at'])).'–'.date('H:i',strtotime($a['end_at']))) ?></dd><dt>Süre</dt><dd><?= (int)((strtotime($a['end_at'])-strtotime($a['start_at']))/60) ?> dakika</dd><dt>Tahmini hizmet tutarı</dt><dd><?= e($money($a['service_price'])) ?> (tahsilat değildir)</dd><dt>Müşteri notu</dt><dd><?= e($a['customer_note']?:'Not eklenmedi') ?></dd></dl>
<div class="wizard-actions"><?php if($permissions['can_confirm']&&$a['status']==='pending'&&strtotime($a['start_at'])>time()): ?><form method="post" action="<?= e(url('employee/appointments/status')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="status" value="confirmed"><button class="btn btn-lumera" type="submit">Randevuyu onayla</button></form><?php endif ?><?php if($permissions['can_complete']&&$a['status']==='confirmed'&&strtotime($a['end_at'])<=time()): ?><form method="post" action="<?= e(url('employee/appointments/status')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="status" value="completed"><button class="btn btn-lumera" type="submit">İşlemi tamamlandı işaretle</button></form><?php endif ?></div>
<?php if($a['status']==='confirmed'&&strtotime($a['end_at'])>time()): ?><p class="muted mt-3">İşlem bitiş saatinden önce tamamlandı işaretlenemez.</p><?php endif ?><?php if(!$permissions['can_confirm']&&$a['status']==='pending'): ?><p class="muted">Onaylama yetkisi yöneticiniz tarafından kapalı tutuluyor.</p><?php endif ?>
<?php $pendingRequest=(bool)array_filter($cancellations,static fn($q)=>$q['status']==='pending');if($permissions['can_request_cancel']&&in_array($a['status'],['pending','confirmed'],true)&&strtotime($a['end_at'])>time()&&!$pendingRequest): ?><hr><form method="post" action="<?= e(url('employee/appointments/cancellation')) ?>" class="admin-form"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><label for="cancel-reason">İptal talebi gerekçesi</label><textarea class="form-control" id="cancel-reason" name="reason" minlength="3" maxlength="1000" required rows="3"></textarea><p class="muted">Talep randevuyu iptal etmez. Son karar yöneticidedir.</p><button class="btn btn-outline-danger" type="submit">İptal talebi oluştur</button></form><?php endif ?></section>
<?php if($cancellations): ?><section class="customer-card mt-4"><h2>İptal talepleri</h2><?php foreach($cancellations as$q): ?><article class="leave-card"><strong><?= e($requestLabels[$q['status']]) ?></strong><p><?= e($q['reason']) ?></p><p><?= e($q['response']??'Yönetici değerlendirmesi bekleniyor.') ?></p></article><?php endforeach ?></section><?php endif ?>
